/// <summary>
/// Check whether an intercompany sales order exists of a given sales order.
/// And, confirm if the intercomapny sales order is invoiced or not.
/// </summary>
/// <param name = "_origShipmentId">Original shipment id</param>
/// <returns>True/false</returns>
public static boolean validateIntercompanyShipment(MetShipmentId _origShipmentId)
{
    boolean                         isValid     = true;
    SalesTable                      origSalesTable, intercompanySalesTable;
    PurchTable                      purchTable_Reference;
    METSalesOrderShipmentLoadLines  origShipmentLoadLines, intercompanyShipmentLoadLines;
    METSalesOrderShipmentLoadHeader origShipmentLoadHeader;

    while select origShipmentLoadLines group by OrderNum
        where origShipmentLoadLines.ShipmentId == _origShipmentId
        join origSalesTable
        where origSalesTable.SalesId == origShipmentLoadLines.OrderNum
        && origSalesTable.METIntercompanyTransferFulfillment == NoYes::Yes
    {
        if (isValid)
        {
            purchTable_Reference = SalesTable::find(origShipmentLoadLines.OrderNum).referencePurchTable();

            changeCompany(purchTable_Reference.InterCompanyCompanyId)
            {
                intercompanySalesTable = purchTable_Reference.interCompanySalesTable();

                if (intercompanySalesTable)
                {
                    select firstonly ShipmentId from intercompanyShipmentLoadLines
                        where intercompanyShipmentLoadLines.OrderNum == intercompanySalesTable.SalesId;

                    if (intercompanySalesTable.SalesStatus != SalesStatus::Invoiced
                        && intercompanySalesTable.SalesStatus != SalesStatus::Canceled)
                    {
                        isValid = false;
                        error(strFmt("@MET:ValidateIntercompanySOFinalization", _origShipmentId, intercompanyShipmentLoadLines.ShipmentId));
                    }
                }
            }
        }

    }
    return isValid;
}

/// <summary>
/// Post intercompany picking list
/// </summary>
public void postIntercompanyPickingList(SalesTable _salesTable)
{
    if (_salesTable)
    {
        PurchTable purchTable_Reference = _salesTable.referencePurchTable();

        if ((!purchTable_Reference.RecId && !purchTable_Reference.InterCompanySalesId) || !TradeInterCompany::checkDataAreaAccess(purchTable_Reference.InterCompanyCompanyId))
        {
            return;
        }
        else if (purchTable_Reference.RecId)
        {
            changeCompany(purchTable_Reference.InterCompanyCompanyId)
            {
                //NS-Bug 187793: CB274 - Batch number not populating on the intercompany sales order line and sales order not auto extracting
                SalesTable intercompanySalesTable = purchTable_Reference.interCompanySalesTable();

                //Do the stock reservation before generating the picking list.
                METStockReservation::construct(intercompanySalesTable).process();

                //Post the picking list of the intercompany sales order.
                this.postPickingList(intercompanySalesTable);
                //NE-Bug 187793: CB274 - Batch number not populating on the intercompany sales order line and sales order not auto extracting
            }
        }
    }

}

/// <summary>
/// Post picking list
/// </summary>
/// <param name = "_salesTable">SalesTable buffer.</param>
private void postPickingList(SalesTable _salesTable)
{
    boolean          isError;
    List             qualifyingSalesLines = new List(Types::Int64);
    Map              qtyOverrideMap       = new Map(Types::Int64, Types::Real);
    SalesLine        salesLineLoc;
    WMSPickingRoute  wmsPickingRoute;

    try
    {
        ttsbegin;

        while select salesLineLoc
            where salesLineLoc.SalesId     == _salesTable.SalesId
               && salesLineLoc.SalesStatus != SalesStatus::Canceled
        {
            if (salesLineLoc.metSalesLine().OrderExtractStatus == METOrderExtractStatus::Open
                    || salesLineLoc.metSalesLine().OrderExtractStatus == METOrderExtractStatus::ReadyForExtract)
            {
                qualifyingSalesLines.addEnd(salesLineLoc.RecId);
                // reservedPhysical() already returns an inventory-unit quantity
                // (confirmed against the standard SalesLine source) - no conversion needed.
                qtyOverrideMap.add(salesLineLoc.RecId, salesLineLoc.reservedPhysical());
            }
        }

        if (!qualifyingSalesLines.empty())
        {
            wmsPickingRoute = METSalesPickListGenerationService::construct()
                .generatePickList(_salesTable, qualifyingSalesLines, false, qtyOverrideMap);
        }

        ttscommit;

        if (wmsPickingRoute)
        {
            if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METPicklistExtractionBusinessEvent)))
            {
                METPicklistExtractionBusinessEvent::newFromWMSPickingRoute(wmsPickingRoute).send();
            }
            else
            {
                error("@MET:PicklistExtractionBusinessEventNotEnabled");
            }
        }
    }
    catch
    {
        error ("@WAX:UpdateCancelled");
        isError = true;
    }

    if (isError)
    {
        // If picking list generation failed with error revert extract status back to Open
        _salesTable.selectForUpdate(true);
        _salesTable.metUpdateExtractStatus();
    }
}

/// <summary>
/// Create the Purchase order.
/// </summary>
/// <param name = "_salesTable">Sales table reference</param>
/// <param name = "_salesLine">Sales line reference</param>
public static void createPOForIntercompanyFulfillment(SalesTable _salesTable, SalesLine _salesLine)
{
    boolean             isIncluded = NoYes::Yes;
    InventTable         inventTable;
    InventTable         inventTableLoc;
    TmpPurchLinePrice   tmpPurchLinePrice;
    SalesLine           salesLine;
    boolean             isValid = false;

    ttsbegin;

    while select forupdate salesLine
        where salesLine.SalesId == _salesTable.SalesId
            && salesLine.SalesStatus != SalesStatus::Canceled
    {
        if (!salesLine.referencedPurchLine() && InventTable::metGetOSCCode(salesLine.ItemId, salesLine.inventDim()) == METConstants::GroceryOscCode)
        {
            //Insert <c>SalesLine</c> record into <c>TmpPurchLinePrice</c>.
            tmpPurchLinePrice.clear();

            tmpPurchLinePrice.SalesId           = salesLine.SalesId;
            tmpPurchLinePrice.LineNum           = salesLine.LineNum;
            tmpPurchLinePrice.PurchQty          = salesLine.SalesQty;
            tmpPurchLinePrice.Included          = isIncluded;

            select firstonly PrimaryVendorId from inventTable
                where inventTable.ItemId == salesLine.ItemId
                && inventTable.PrimaryVendorId != '';

            if (inventTable.PrimaryVendorId)
            {
                tmpPurchLinePrice.AccountNum        = inventTable.PrimaryVendorId;
                tmpPurchLinePrice.SalesLineRefRecId = salesLine.RecId;
                tmpPurchLinePrice.PurchUnit         = salesLine.SalesUnit;

                tmpPurchLinePrice.insert();
                isValid = true;
            }
            else
            {
                throw error(strFmt("@MET:MissingPrimaryVendorForGroceryItem", salesLine.ItemId));
            }
        }
    }

    if (isValid)
    {
        //Create the purchase order from the extracted sales order.
        PurchCreateFromSalesOrder purchCreateFromSalesOrder = PurchCreateFromSalesOrder::newPurchCreateFromSalesOrder(TradeLineDlvType::None);
        purchCreateFromSalesOrder.parmSalesTable(_salesTable);
        purchCreateFromSalesOrder.parmCallerRecord(_salesTable);
        purchCreateFromSalesOrder.parmTmpPurchLinePrice(tmpPurchLinePrice);
        purchCreateFromSalesOrder.runOperation();
    }

    ttscommit;

}

/// <summary>
/// Update the PO and original SO after the intercompany SO finalization.
/// Confirm the purchase order and post the purchase order product receipt automatically in the liquor legal entity.
/// And the invoice number should be used as product receipt number.
/// Post the picking list registration for the original sales order in the Liquor legal entity.
/// </summary>
/// <param name = "_salesId"></param>
public static void processPostIntercompanySOFinalization(SalesId _salesId, InvoiceId _invoiceId)
{
    InventQty           salesQty;
    SalesLine           salesLine;
    SalesTable          salesTable = SalesTable::find(_salesId);
    METSalesLine        metSalesLine;
    SalesInvoicedQty    invoicedQty;

    //Loop through the intercompany sales order.
    while select salesLine
        where salesLine.SalesId == salesTable.SalesId
        exists join metSalesLine
        where metSalesLine.SalesLine == salesLine.RecId
            && metSalesLine.OrderExtractStatus == METOrderExtractStatus::Extracted
    {
        CustInvoiceTrans custInvoiceTrans;

        //Get the invoice quantity.
        select firstonly Qty from custInvoiceTrans
            where custInvoiceTrans.InvoiceId == _invoiceId
            && custInvoiceTrans.ItemId == salesLine.ItemId;

        if (custInvoiceTrans.Qty)
        {
            invoicedQty = custInvoiceTrans.Qty;
        }

        //Get the sales line quantity.
        salesQty = salesLine.calcQtyOrdered();

        //Change the company to the original company of the intercompany sales order.
        changecompany(InventParameters::find().METInterCompanyPurchaseLegalEntity)
        {
            SalesTable  origSalesTable          = SalesTable::find(salesTable.InterCompanyOriginalSalesId);
            PurchTable  purchTable_Reference    = PurchTable::find(salesTable.InterCompanyPurchId);

            if (purchTable_Reference.RecId)
            {
                //Confirm and receive the purchase order which was created as part of the process in the original legal entity.
                METPurchaseOrderProcessHelper::confirmPurchaseOrder(purchTable_Reference.PurchId);
                METPurchaseOrderProcessHelper::postPurchaseOrderProductReceipt(purchTable_Reference, _invoiceId, invoicedQty);
            }

            if (invoicedQty)
            {
                List qualifyingSalesLines;

                qualifyingSalesLines = METSalesOrderProcessHelper::calcQueryForOriginalSO(origSalesTable.SalesId, salesLine.ItemId, invoicedQty);
                METSalesOrderProcessHelper::postPickingListForOrigSO(origSalesTable, qualifyingSalesLines, invoicedQty);
            }
        }
    }
}

/// <summary>
/// Post the pick list for the food item on the original sales order.
/// </summary>
/// <param name = "_salesTable">SalesTable</param>
/// <param name = "_qualifyingSalesLines">List of qualifying SalesLine RecIds, from calcQueryForOriginalSO</param>
/// <param name = "_pickListOrderedQty">boolean</param>
private static void postPickingListForOrigSO(SalesTable _salesTable, List _qualifyingSalesLines, SalesInvoicedQty _invoicedQty,
    boolean _pickListOrderedQty = false)
{
    boolean             isError     = false;
    SalesTable          salesTable  = SalesTable::find(_salesTable.SalesId);
    WMSPickingRoute     wmsPickingRoute;
    List                qualifyingLines = _qualifyingSalesLines;
    Map                 qtyOverrideMap  = new Map(Types::Int64, Types::Real);
    SalesLine           salesLineLoc;

    try
    {
        ttsbegin;

        if (_pickListOrderedQty == false)
        {
            ListEnumerator le = _qualifyingSalesLines.getEnumerator();

            while (le.moveNext())
            {
                select firstonly salesLineLoc where salesLineLoc.RecId == le.current();

                if (salesLineLoc.RecId)
                {
                    if (salesLineLoc.metSalesLine().OrderExtractStatus == METOrderExtractStatus::Open ||
                            salesLineLoc.metSalesLine().OrderExtractStatus == METOrderExtractStatus::ReadyForExtract)
                    {
                        qtyOverrideMap.add(salesLineLoc.RecId,
                            METSalesPickListGenerationService::convertSalesUnitQtyToInventUnit(salesLineLoc, salesLineLoc.reservedPhysicalInSalesUnit()));
                    }
                    else
                    {
                        qtyOverrideMap.add(salesLineLoc.RecId,
                            METSalesPickListGenerationService::convertSalesUnitQtyToInventUnit(salesLineLoc, _invoicedQty));
                    }
                }
            }
        }
        else
        {
            Info(strfmt("@MET:SOPickListForOrderQty", _salesTable.SalesId));
        }

        if (!qualifyingLines.empty())
        {
            wmsPickingRoute = METSalesPickListGenerationService::construct()
                .generatePickList(salesTable, qualifyingLines, _pickListOrderedQty, qtyOverrideMap);
        }

        ttscommit;

        if (wmsPickingRoute)
        {
            //Complete the picking list registration.
            METSalesOrderProcessHelper::pickingListRegisteration(wmsPickingRoute.pickingRouteID);

            if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METPicklistExtractionBusinessEvent)))
            {
                METPicklistExtractionBusinessEvent::newFromWMSPickingRoute(wmsPickingRoute).send();
            }
            else
            {
                error("@MET:PicklistExtractionBusinessEventNotEnabled");
            }
        }
    }
    catch
    {
        error ("@WAX:UpdateCancelled");
        isError = true;
    }

    salesTable.reread();
    salesTable.selectForUpdate(true);
    salesTable.metUpdateExtractStatus();

    if (!isError)
    {
        //CB625_TMSSOPickingListExtraction
        if (salesTable.METOrderExtractStatus == METOrderExtractStatus::Extracted)
        {
            METTMSEngineOrderProccess  metTMSEngineOrderProccess = METTMSEngineOrderProccess::construct(METTMSEngineExecutionMode::SalesOrderPickingList, salesTable, wmsPickingRoute.PickingRouteID);
            metTMSEngineOrderProccess.run();
        }
    }
}

/// <summary>
/// Complete the picking list registration.
/// </summary>
/// <param name = "_pickingRouteID">WMSPickingRouteID</param>
public static void pickingListRegisteration(WMSPickingRouteID _pickingRouteID)
{
    List list = new List(Types::String);

    list.addEnd(_pickingRouteID);

    WMSPickingRoute::finishMulti(list.pack());
}

/// <summary>
/// Created for the CB274 - Intercompany Transfers.
/// Include the SO line for extraction if it's a food item.
/// </summary>
/// <param name = "_salesId">Sales ID</param>
/// <param name = "_itemId">Item ID</param>
/// <param name = "_invoicedQty">Invoiced quantity</param>
/// <returns>List of qualifying SalesLine RecIds</returns>
private static List calcQueryForOriginalSO(SalesId _salesId, ItemId _itemId, SalesInvoicedQty _invoicedQty)
{
    List                     qualifyingSalesLines = new List(Types::Int64);
    SalesLine                origSalesLine;

    ttsbegin;
    while select origSalesLine
        where origSalesLine.SalesId == _salesId
            && origSalesLine.ItemId == _itemId
    {
        if (InventTable::metGetOSCCode(origSalesLine.ItemId, origSalesLine.inventDim()) == METConstants::GroceryOscCode)
        {

            if (_invoicedQty < origSalesLine.SalesQty)
            {
                //If the invoiced quantity is less than the sales line quantity, then update the delivery reminder on the sales line (Short pick).
                METSalesOrderProcessHelper::updateDeliveryReminder(origSalesLine, _invoicedQty);
            }

            qualifyingSalesLines.addEnd(origSalesLine.RecId);
        }
    }
    ttscommit;
    return qualifyingSalesLines;
}

/// <summary>
/// Update the PO and confirm it.
/// </summary>
/// <param name = "_salesLine">Sales line</param>
public void updateIntercompanyPOAndConfirm(SalesLine _salesLine, InventQty _pickedQty)
{
    PurchId         purchId = _salesLine.METReplenishmentPOReference;
    InventQty       newRemainInventPhysical = 0;
    InventQty       newRemainPurchPhysical  = 0;
    PurchLine       purchLine;
    PurchTable      purchTable;
    PdsCWInventQty  newPdsCWRemainInventPhysical = 0;

    Factor                  factor;
    UnitOfMeasureFromRecId  fromUnit, toUnit;

    //Get the unit conversion rule and factor.
    fromUnit    = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(_salesLine.SalesUnit);
    toUnit      = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(InventTableModule::find(_salesLine.ItemId, ModuleInventPurchSales::Invent).UnitId);
    factor      = EcoResProductUnitConverter::convertForReleasedProduct(
                                _salesLine.ItemId,
                                _salesLine.inventDimId,
                                1,
                                fromUnit,
                                toUnit,
                                NoYes::No,
                                NoYes::No);

    changecompany(InventParameters::find().METInterCompanyPurchaseLegalEntity)
    {
        purchTable = PurchTable::find(purchId);

        if (purchTable.METIntercompanyTransferReplenishment == NoYes::Yes)
        {
            select firstonly purchLine
                where purchLine.PurchId == purchId
                && purchLine.ItemId == _salesLine.ItemId
                && purchLine.METReplenishmentSOReference == _salesLine.SalesId;

            if (!purchLine.RecId)
            {
                checkFailed(strFmt("@MET:METNoMatchingPOReplenishmentReferenceFound", _salesLine.SalesId, _salesLine.InventTransId, purchId, _salesLine.ItemId));
            }
            else
            {
                ttsbegin;
                purchLine.selectForUpdate(true);
                purchLine.PurchQty              = _pickedQty/factor;
                purchLine.RemainPurchPhysical   = _pickedQty/factor;
                purchLine.RemainInventPhysical  = _pickedQty;

                PurchLine::modifyPurchQty(purchLine, InventDim::find(purchLine.InventDimId), false);
                InventMovement::bufferSetRemainQty(purchLine);

                purchLine.update();
                ttscommit;

                //Auto-confirm the purchase order.
                METPurchaseOrderProcessHelper::confirmPurchaseOrder(purchLine.PurchId);
            }
        }
        else
        {
            checkFailed(strFmt("@MET:METICReplenishmentPONotMarked", _salesLine.SalesId, _salesLine.InventTransId, purchId));
        }
    }
}

/// <summary>
/// If the transfer order line is not fully reserved, then update the delivery remainder on the sales line.
/// </summary>
/// <param name = "_inventTransferLine"><t>InventTransferLine</t> table buffer</param>
/// <param name = "_salesLine"><t>SalesLine</t> table buffer</param>
public static void updateDeliveryReminder(SalesLine _salesLine, Qty _pickedQty)
{
    Factor                  factor;
    UnitOfMeasureFromRecId  fromUnit, toUnit;

    //Get the unit conversion rule and factor.
    fromUnit    = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(_salesLine.SalesUnit);
    toUnit      = EcoResReleasedProductUnitConverter::findUnitRecIdBySymbol(InventTableModule::find(_salesLine.ItemId, ModuleInventPurchSales::Invent).UnitId);
    factor      = EcoResProductUnitConverter::convertForReleasedProduct(
                                _salesLine.ItemId,
                                _salesLine.inventDimId,
                                1,
                                fromUnit,
                                toUnit,
                                NoYes::No,
                                NoYes::No);

    // Update the SO line's delivery remainder fields
    SalesLine salesLineUpd = SalesLine::findInventTransId(_salesLine.InventTransId, true);

    if (salesLineUpd)
    {
        SalesUpdateRemain salesUpdateRemain = SalesUpdateRemain::construct();

        salesUpdateRemain.updateDeliverRemainder(
            salesLineUpd,
            salesLineUpd.RemainSalesPhysical - _pickedQty,
            salesLineUpd.RemainInventPhysical - (_pickedQty * factor));
    }
}

/// <summary>
/// Get the intercompany sales line for a given original sales line.
/// </summary>
/// <param name = "_salesId">Sales id</param>
/// <param name = "_itemId">Item id</param>
/// <param name = "_inventDim">Inventory dimension id</param>
/// <returns>Sales line</returns>
public static SalesLine getInterCompanySalesLine(InterCompanyOriginalSalesId _salesId, 
    SalesLine _origSalesLine, InventDim _inventDim)
{
    InventDim   interCompanyInventDim;
    SalesLine   interCompanySalesLine;

    select firstonly interCompanySalesLine
        where interCompanySalesLine.SalesId == _salesId
            && interCompanySalesLine.ItemId == _origSalesLine.ItemId
        join interCompanyInventDim
        where interCompanyInventDim.inventBatchId == _inventDim.inventBatchId
            && interCompanyInventDim.InventSiteId == _inventDim.InventSiteId
            && interCompanyInventDim.InventLocationId == _inventDim.InventLocationId
            && interCompanyInventDim.WMSLocationId == _inventDim.WMSLocationId;

    return interCompanySalesLine;
}
